import { basePath } from '../config/site';

export interface SiteImage {
  /** Base name of the generated files in public/images. */
  name: string;
  widths: number[];
  /** Intrinsic aspect ratio of the source (width / height). */
  width: number;
  height: number;
  alt: string;
  credit: { photographer: string; url: string };
}

const image = (img: SiteImage) => img;

export const images = {
  hero: image({
    name: 'hero-highway',
    widths: [640, 1280, 1920],
    width: 1920,
    height: 1280,
    alt: 'Tractor-trailers travelling along a highway through rolling hills',
    credit: { photographer: 'Bhargav Panchal', url: 'https://unsplash.com/photos/P0bVatS8Jdw' },
  }),
  intermodal: image({
    name: 'intermodal-container',
    widths: [640, 1024, 1600],
    width: 1600,
    height: 1040,
    alt: 'Shipping container loaded on a truck chassis in front of stacked intermodal containers',
    credit: { photographer: 'Bernd Dittrich', url: 'https://unsplash.com/photos/Xk1IfNnEhRA' },
  }),
  openRoad: image({
    name: 'open-road-truck',
    widths: [640, 1024, 1600],
    width: 1600,
    height: 831,
    alt: 'Semi-truck with a dry van trailer parked on open pavement with hills behind',
    credit: { photographer: 'Sander Yigin', url: 'https://unsplash.com/photos/ki19VJAGh6w' },
  }),
  nightHighway: image({
    name: 'night-highway',
    widths: [640, 1280, 1920],
    width: 1920,
    height: 1280,
    alt: 'Orange semi-truck with its lights on, driving on a highway at dusk',
    credit: { photographer: 'Nishat Samadzai', url: 'https://unsplash.com/photos/RxVtDbR00cg' },
  }),
};

export const imageSrc = (img: SiteImage, width = img.widths[img.widths.length - 1]) =>
  `${basePath}/images/${img.name}-${width}.webp`;

export const imageSrcSet = (img: SiteImage) =>
  img.widths.map((w) => `${imageSrc(img, w)} ${w}w`).join(', ');

/** Relative to the site URL, which already includes any base path. */
export const ogImagePath = '/images/og-image.jpg';
